<section class="page-heading"><span class="eyebrow">Your workspace</span><h1>Assessment history</h1><p>Each saved outcome uses the profile snapshot and rule version recorded at the time.</p></section><?php if(!$assessments): ?><div class="empty-state"><h2>No assessments yet</h2><p>Open an active scheme and run a preliminary check.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Scheme</th><th>Assessed</th><th>Outcome</th><th>Rule version</th><th></th></tr></thead><tbody><?php foreach($assessments as $a): ?><tr><td><?=e($a['title'])?> <?=$a['is_demo']?'<span class="badge badge-demo">DEMO</span>':''?></td><td><?=e($a['assessed_at'])?></td><td><span class="badge badge-status"><?=e(str_replace('_',' ',$a['overall_status']))?></span></td><td><?=e($a['rule_version'])?></td><td><a href="<?=e(url('result',['id'=>$a['id']]))?>">Review</a></td></tr><?php endforeach; ?></tbody></table></div><div class="pagination"><a href="<?=e(url('history',['p'=>max(1,$pageNo-1)]))?>">← Previous</a><span>Page <?=e($pageNo)?></span><a href="<?=e(url('history',['p'=>$pageNo+1]))?>">Next →</a></div><?php endif; ?>
